import express from 'express';
import cors from 'cors';
import { DatabaseSync } from 'node:sqlite';
import crypto from 'crypto';
import path from 'path';
import { fileURLToPath } from 'url';
import fs from 'fs';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const logsDir = path.join(__dirname, 'logs');
if (!fs.existsSync(logsDir)) fs.mkdirSync(logsDir);
const dbLog = (event, data) => {
  const ts = new Date().toISOString().split('T')[0] + ' ' + new Date().toISOString().split('T')[1].slice(0, 8);
  const pairs = Object.entries(data).map(([k, v]) => `${k}=${v}`).join(' | ');
  fs.appendFileSync(path.join(logsDir, 'database.log'), `${ts} | ${event} | ${pairs}\n`);
};
const DB_PATH = process.env.DB_PATH || path.join(__dirname, 'components.db');
const db = new DatabaseSync(DB_PATH);
// node:sqlite has no transaction() helper; better-sqlite3's shape, minus savepoint nesting.
db.transaction = (fn) => (...args) => {
  db.exec('BEGIN');
  try { const r = fn(...args); db.exec('COMMIT'); return r; }
  catch (e) { db.exec('ROLLBACK'); throw e; }
};

db.exec(`
  CREATE TABLE IF NOT EXISTS categories (
    id INTEGER PRIMARY KEY,
    name TEXT UNIQUE NOT NULL
  );
  CREATE TABLE IF NOT EXISTS packages (
    id INTEGER PRIMARY KEY,
    name TEXT UNIQUE NOT NULL
  );
  CREATE TABLE IF NOT EXISTS locations (
    id INTEGER PRIMARY KEY,
    main TEXT NOT NULL,
    secondary TEXT NOT NULL,
    UNIQUE(main, secondary)
  );
  CREATE TABLE IF NOT EXISTS components (
    inventory_key TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    category TEXT NOT NULL,
    package TEXT,
    in_stock INTEGER DEFAULT 0,
    location TEXT,
    manufacturer_nr TEXT
  );
  CREATE TABLE IF NOT EXISTS reports (
    id INTEGER PRIMARY KEY,
    inventory_key TEXT NOT NULL,
    report_type TEXT NOT NULL,
    timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY(inventory_key) REFERENCES components(inventory_key)
  );
  CREATE TABLE IF NOT EXISTS suggested_components (
    inventory_key TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    category TEXT NOT NULL,
    package TEXT,
    in_stock INTEGER DEFAULT 0,
    location TEXT,
    manufacturer_nr TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE TABLE IF NOT EXISTS real_number_reports (
    id INTEGER PRIMARY KEY,
    inventory_key TEXT NOT NULL,
    reported_number INTEGER NOT NULL,
    timestamp DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY(inventory_key) REFERENCES components(inventory_key)
  )
`);

const app = express();
app.use(cors());
app.use(express.json());

// Admin gate. Hashing both sides gives timingSafeEqual the equal lengths it requires.
// ponytail: one shared password, sent cleartext over LAN HTTP. Fine for a lab box;
// move to accounts + TLS if this ever leaves the local network.
const ADMIN_PW = process.env.ADMIN_PASSWORD || '123456789';
const pwHash = (s) => crypto.createHash('sha256').update(String(s)).digest();
const requireAdmin = (req, res, next) =>
  crypto.timingSafeEqual(pwHash(req.get('x-admin-password')), pwHash(ADMIN_PW))
    ? next()
    : res.status(401).json({ error: 'Unauthorized' });

app.get('/api/admin/check', requireAdmin, (req, res) => res.json({ ok: true }));

app.get('/api/categories', (req, res) => {
  try {
    const rows = db.prepare(`SELECT * FROM categories ORDER BY name`).all();
    res.json(rows);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post('/api/categories', (req, res) => {
  try {
    db.prepare(`INSERT OR IGNORE INTO categories (name) VALUES (?)`).run(req.body.name);
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get('/api/packages', (req, res) => {
  try {
    const rows = db.prepare(`SELECT * FROM packages ORDER BY name`).all();
    res.json(rows);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post('/api/packages', (req, res) => {
  try {
    db.prepare(`INSERT OR IGNORE INTO packages (name) VALUES (?)`).run(req.body.name);
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get('/api/locations', (req, res) => {
  try {
    const rows = db.prepare(`SELECT * FROM locations ORDER BY main, secondary`).all();
    res.json(rows);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// A main name holding the ' - ' separator would make the display string ambiguous to split.
app.post('/api/locations', (req, res) => {
  const main = String(req.body.main || '').trim();
  const secondary = String(req.body.secondary || '').trim();
  if (!main || !secondary) return res.status(400).json({ error: 'main and secondary required' });
  if (main.includes(' - ')) return res.status(400).json({ error: "main cannot contain ' - '" });
  try {
    db.prepare(`INSERT OR IGNORE INTO locations (main, secondary) VALUES (?, ?)`).run(main, secondary);
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get('/api/components', (req, res) => {
  const search = req.query.search || '';
  const category = req.query.category || '';
  let query = `SELECT * FROM components WHERE 1=1`;
  const params = [];

  if (search) {
    query += ` AND (name LIKE ? OR inventory_key LIKE ?)`;
    params.push(`%${search}%`, `%${search}%`);
  }
  if (category) {
    query += ` AND category = ?`;
    params.push(category);
  }

  try {
    const rows = db.prepare(query).all(...params);
    res.json(rows);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post('/api/components', requireAdmin, (req, res) => {
  const { inventory_key, name, category, package: pkg, in_stock, location, manufacturer_nr } = req.body;
  try {
    db.prepare(
      `INSERT INTO components VALUES (?, ?, ?, ?, ?, ?, ?)`
    ).run(inventory_key, name, category, pkg, in_stock, location, manufacturer_nr);
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Edit an existing part. inventory_key is the identity the reports hang off by FK,
// so it is read from the URL and never written.
app.put('/api/components/:key', requireAdmin, (req, res) => {
  const { name, category, package: pkg, in_stock, location, manufacturer_nr } = req.body;
  if (!name || !category) return res.status(400).json({ error: 'name and category required' });
  try {
    const r = db.prepare(`UPDATE components SET name=?, category=?, package=?, in_stock=?, location=?, manufacturer_nr=? WHERE inventory_key=?`)
      .run(name, category, pkg ?? null, Number(in_stock) || 0, location ?? null, manufacturer_nr ?? null, req.params.key);
    if (!r.changes) return res.status(404).json({ error: 'No such component' });
    dbLog('COMPONENT_EDITED', { key: req.params.key, name, category, package: pkg, in_stock, location, manufacturer_nr });
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// reports and real_number_reports both hold a FK to components, so the part cannot
// go until its dependents do. The file audit log in logs/ keeps the permanent history.
app.delete('/api/components/:key', requireAdmin, (req, res) => {
  try {
    const removed = db.transaction((key) => {
      db.prepare(`DELETE FROM reports WHERE inventory_key=?`).run(key);
      db.prepare(`DELETE FROM real_number_reports WHERE inventory_key=?`).run(key);
      return db.prepare(`DELETE FROM components WHERE inventory_key=?`).run(key).changes;
    })(req.params.key);
    dbLog('COMPONENT_DELETED', { key: req.params.key, existed: removed > 0 });
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.get('/api/suggested_components', (req, res) => {
  try {
    const rows = db.prepare(`SELECT * FROM suggested_components ORDER BY created_at DESC`).all();
    res.json(rows);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post('/api/suggested_components', (req, res) => {
  const { inventory_key, name, category, package: pkg, in_stock, location, manufacturer_nr } = req.body;
  try {
    db.prepare(
      `INSERT INTO suggested_components (inventory_key, name, category, package, in_stock, location, manufacturer_nr) VALUES (?, ?, ?, ?, ?, ?, ?)
       ON CONFLICT(inventory_key) DO UPDATE SET name=excluded.name, category=excluded.category, package=excluded.package,
       in_stock=excluded.in_stock, location=excluded.location, manufacturer_nr=excluded.manufacturer_nr, created_at=CURRENT_TIMESTAMP`
    ).run(inventory_key, name, category, pkg, in_stock, location, manufacturer_nr);
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.delete('/api/suggested_components/:key', requireAdmin, (req, res) => {
  try {
    db.prepare(`DELETE FROM suggested_components WHERE inventory_key=?`).run(req.params.key);
    dbLog('SUGGESTION_REJECTED', { key: req.params.key });
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post('/api/suggested_components/:key/approve', requireAdmin, (req, res) => {
  try {
    const s = db.prepare(`SELECT * FROM suggested_components WHERE inventory_key=?`).get(req.params.key);
    if (!s) return res.status(404).json({ error: 'No such suggestion' });
    db.transaction(() => {
      db.prepare(`INSERT INTO components (inventory_key, name, category, package, in_stock, location, manufacturer_nr) VALUES (?, ?, ?, ?, ?, ?, ?)
         ON CONFLICT(inventory_key) DO UPDATE SET name=excluded.name, category=excluded.category, package=excluded.package,
         in_stock=excluded.in_stock, location=excluded.location, manufacturer_nr=excluded.manufacturer_nr`)
        .run(s.inventory_key, s.name, s.category, s.package, s.in_stock, s.location, s.manufacturer_nr);
      db.prepare(`DELETE FROM suggested_components WHERE inventory_key=?`).run(req.params.key);
    })();
    dbLog('SUGGESTION_APPROVED', { key: s.inventory_key, name: s.name });
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// LEFT JOIN is defensive: deleting a part now clears its reports, so a null name
// would mean a row got orphaned some other way. Better to show it than to hide it.
app.get('/api/reports', requireAdmin, (req, res) => {
  try {
    const rows = db.prepare(`
      SELECT r.id, r.inventory_key, r.report_type, r.timestamp, c.name
      FROM reports r
      LEFT JOIN components c ON c.inventory_key = r.inventory_key
      ORDER BY r.timestamp DESC, r.id DESC
    `).all();
    res.json(rows);
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post('/api/reports', (req, res) => {
  const { inventory_key, report_type } = req.body;
  try {
    db.prepare(`INSERT INTO reports (inventory_key, report_type) VALUES (?, ?)`).run(inventory_key, report_type);
    dbLog('REPORT_ADDED', { key: inventory_key, type: report_type });
    if (report_type === 'Not in stock') {
      const count = db.prepare(`SELECT COUNT(*) as cnt FROM reports WHERE inventory_key = ? AND report_type = 'Not in stock'`).get(inventory_key).cnt;
      if (count >= 2) {
        db.prepare(`UPDATE components SET in_stock = 0 WHERE inventory_key = ?`).run(inventory_key);
        dbLog('AUTO_ZERO', { key: inventory_key, count, in_stock_set_to: 0 });
      }
    }
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post('/api/components/:key/use', (req, res) => {
  const { amount, action } = req.body;
  try {
    const comp = db.prepare(`SELECT in_stock FROM components WHERE inventory_key = ?`).get(req.params.key);
    const delta = action === 'take' ? -amount : amount;
    const newStock = Math.max(0, comp.in_stock + delta);
    db.prepare(`UPDATE components SET in_stock = ? WHERE inventory_key = ?`).run(newStock, req.params.key);
    db.prepare(`UPDATE real_number_reports SET reported_number = reported_number + ? WHERE inventory_key = ?`).run(delta, req.params.key);
    dbLog('USE_ACTION', { key: req.params.key, action, amount, delta, new_in_stock: newStock });
    res.json({ success: true, in_stock: newStock });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

app.post('/api/components/:key/report-real', (req, res) => {
  const { reported_number } = req.body;
  try {
    const count = db.prepare(`SELECT COUNT(*) as cnt FROM real_number_reports WHERE inventory_key = ? AND reported_number = ?`).get(req.params.key, reported_number).cnt;
    if (count >= 1) {
      db.prepare(`UPDATE components SET in_stock = ? WHERE inventory_key = ?`).run(reported_number, req.params.key);
      db.prepare(`DELETE FROM real_number_reports WHERE inventory_key = ?`).run(req.params.key);
      dbLog('REPORT_REAL_MATCH', { key: req.params.key, reported_number, in_stock_updated: reported_number });
    } else {
      db.prepare(`INSERT INTO real_number_reports (inventory_key, reported_number) VALUES (?, ?)`).run(req.params.key, reported_number);
      dbLog('REPORT_REAL_NEW', { key: req.params.key, reported_number });
    }
    res.json({ success: true });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

const PORT = process.env.PORT || 3001;
app.listen(PORT, () => console.log(`Backend running on port ${PORT}`));
// Which component rows a given admin view shows. Kept out of App.jsx so it can be
// checked by test_views.js without React or a bundler.
export const visibleRows = (components, view, lowThreshold, filterZeroStock) =>
  view === 'suggested'
    ? []
    : components.filter((c) => {
        if (view === 'out') return c.in_stock === 0
        if (view === 'low') return c.in_stock > 0 && c.in_stock <= lowThreshold
        return filterZeroStock || c.in_stock > 0
      })

// A location lives in components.location as one "Main - Secondary" display string.
// The two entry dropdowns derive their values back out of it, so the table cells,
// the POST payload and visibleRows above all stay unaware of the split.
export const LOC_SEP = ' - '

export const splitLoc = (location) => {
  const [main = '', secondary = ''] = String(location || '').split(LOC_SEP)
  return { main, secondary }
}

export const joinLoc = (main, secondary) => (main && secondary ? main + LOC_SEP + secondary : main || '')

// Rows are grouped by category, then package, so same-kind parts sit together; the user
// only picks the direction of the name sort inside those groups.
// Natural, case-insensitive compare: this inventory is full of names like "22 Ohm 1%" and
// "100 Ohm 1%", which a plain string sort would order 100 before 22.
const cmp = (a, b) =>
  String(a ?? '').localeCompare(String(b ?? ''), undefined, { numeric: true, sensitivity: 'base' })

export const sortRows = (rows, nameDir = 'asc') =>
  [...rows].sort(
    (a, b) =>
      cmp(a.category, b.category) ||
      cmp(a.package, b.package) ||
      (nameDir === 'desc' ? cmp(b.name, a.name) : cmp(a.name, b.name))
  )
import { DatabaseSync } from 'node:sqlite';

const db = new DatabaseSync('components.db');
console.log('Tables:', db.prepare("SELECT name FROM sqlite_master WHERE type='table'").all().map(t => t.name));
console.log('Categories:', db.prepare('SELECT * FROM categories').all());
console.log('Packages:', db.prepare('SELECT * FROM packages').all());
// Proves the admin gate is real: run `node test_admin.js`.
// Spawns its own server on a throwaway DB, so it never touches components.db.
import assert from 'assert';
import { spawn } from 'child_process';
import fs from 'fs';
import os from 'os';
import path from 'path';

const PW = 'test-password';
const PORT = 3999;
const URL = `http://localhost:${PORT}/api`;
const DB = path.join(os.tmpdir(), `admin-test-${Date.now()}.db`);

const srv = spawn(process.execPath, ['server.js'], {
  env: { ...process.env, DB_PATH: DB, PORT: String(PORT), ADMIN_PASSWORD: PW },
  stdio: 'ignore'
});

const admin = { 'Content-Type': 'application/json', 'x-admin-password': PW };
const plain = { 'Content-Type': 'application/json' };

const ready = async () => {
  for (let i = 0; i < 50; i++) {
    try { await fetch(`${URL}/components`); return; } catch { await new Promise(r => setTimeout(r, 100)); }
  }
  throw new Error('server never came up');
};

const body = (key) => JSON.stringify({
  inventory_key: key, name: 'Test Part', category: 'resistor',
  package: '0805', in_stock: 5, location: 'A1', manufacturer_nr: 'MFR-1'
});

try {
  await ready();

  // --- the gate rejects everything without the right password ---
  assert.equal((await fetch(`${URL}/components`, { method: 'POST', headers: plain, body: body('k1') })).status, 401, 'add with no password must 401');
  assert.equal((await fetch(`${URL}/components`, { method: 'POST', headers: { ...plain, 'x-admin-password': 'REDACTED' }, body: body('k1') })).status, 401, 'add with REDACTED password must 401');
  assert.equal((await fetch(`${URL}/components/k1`, { method: 'DELETE' })).status, 401, 'delete with no password must 401');
  assert.equal((await fetch(`${URL}/admin/check`)).status, 401, 'check with no password must 401');

  // nothing leaked through
  assert.equal((await (await fetch(`${URL}/components`)).json()).length, 0, 'rejected writes must not reach the db');

  // --- the gate opens with the right password ---
  assert.ok((await fetch(`${URL}/admin/check`, { headers: admin })).ok, 'check with correct password must pass');
  assert.ok((await fetch(`${URL}/components`, { method: 'POST', headers: admin, body: body('k1') })).ok, 'add with correct password must succeed');
  assert.equal((await (await fetch(`${URL}/components`)).json()).length, 1, 'component should now exist');

  assert.ok((await fetch(`${URL}/components/k1`, { method: 'DELETE', headers: admin })).ok, 'delete with correct password must succeed');
  assert.equal((await (await fetch(`${URL}/components`)).json()).length, 0, 'component should be gone');

  // --- approving a suggestion moves it into the inventory ---
  await fetch(`${URL}/suggested_components`, { method: 'POST', headers: plain, body: body('s1') });
  assert.equal((await fetch(`${URL}/suggested_components/s1/approve`, { method: 'POST' })).status, 401, 'approve with no password must 401');

  assert.ok((await fetch(`${URL}/suggested_components/s1/approve`, { method: 'POST', headers: admin })).ok, 'approve must succeed');
  assert.equal((await (await fetch(`${URL}/components`)).json()).length, 1, 'approved suggestion must land in components');
  assert.equal((await (await fetch(`${URL}/suggested_components`)).json()).length, 0, 'approved suggestion must leave the queue');

  assert.equal((await fetch(`${URL}/suggested_components/s1/approve`, { method: 'POST', headers: admin })).status, 404, 'approving a gone suggestion must 404');

  // --- everyday lab actions stay open: gating them would break the app ---
  assert.ok((await fetch(`${URL}/components/s1/use`, { method: 'POST', headers: plain, body: JSON.stringify({ amount: 2, action: 'take' }) })).ok, 'take must not need a password');
  assert.ok((await fetch(`${URL}/reports`, { method: 'POST', headers: plain, body: JSON.stringify({ inventory_key: 's1', report_type: 'Low on stock' }) })).ok, 'reporting must not need a password');
  assert.ok((await fetch(`${URL}/suggested_components`, { method: 'POST', headers: plain, body: body('s2') })).ok, 'suggesting must not need a password');


  // --- reading reports is admin-only and joins to the component name ---
  assert.equal((await fetch(`${URL}/reports`)).status, 401, 'listing reports must need a password');
  const list = await (await fetch(`${URL}/reports`, { headers: admin })).json();
  assert.equal(list.length, 1, 'the report filed above must come back');
  assert.equal(list[0].report_type, 'Low on stock', 'report type must round-trip');
  assert.equal(list[0].name, 'Test Part', 'report must carry the component name');

  // deleting a part must succeed even though reports hold a FK to it, and must take them with it
  assert.ok((await fetch(`${URL}/components/s1`, { method: 'DELETE', headers: admin })).ok, 'deleting a reported part must not fail on the FK');
  const afterDelete = await (await fetch(`${URL}/reports`, { headers: admin })).json();
  assert.equal(afterDelete.length, 0, 'deleting a part must clear its reports, not fail on the FK');

  console.log('admin gate ok');
} finally {
  const exited = new Promise((r) => srv.once('exit', r));
  srv.kill();
  await exited; // Windows keeps the sqlite handle open until the child is really gone
  fs.rmSync(DB, { force: true, maxRetries: 10, retryDelay: 100 });
}
// Checks the location split/join round-trip: node test_locations.js
import assert from 'assert';
import { splitLoc, joinLoc } from './src/views.js';

// the display string the user asked for
assert.equal(joinLoc('Regal 1', 'Shelve 1'), 'Regal 1 - Shelve 1');

// round-trip: what the dropdowns read back is what they wrote
const r = splitLoc(joinLoc('Regal 1', 'Shelve 1'));
assert.deepEqual(r, { main: 'Regal 1', secondary: 'Shelve 1' });

// main chosen, shelf not yet: no dangling separator
assert.equal(joinLoc('Regal 1', ''), 'Regal 1');
assert.deepEqual(splitLoc('Regal 1'), { main: 'Regal 1', secondary: '' });

// nothing chosen, and the legacy free-text rows already in the DB
assert.equal(joinLoc('', ''), '');
assert.deepEqual(splitLoc(''), { main: '', secondary: '' });
assert.deepEqual(splitLoc(null), { main: '', secondary: '' });
assert.deepEqual(splitLoc('afaf'), { main: 'afaf', secondary: '' });

// a hyphen inside a name is fine, only the padded ' - ' separates
assert.deepEqual(splitLoc(joinLoc('Regal-A', 'Shelve-2')), { main: 'Regal-A', secondary: 'Shelve-2' });

console.log('location split/join ok');
// Checks grouping + name direction: node test_sort.js
import assert from 'assert';
import { sortRows } from './src/views.js';

const parts = [
  { name: '100 Ohm 1%', category: 'resistor', package: '0805' },
  { name: '22 Ohm 1%', category: 'resistor', package: '0805' },
  { name: 'Tweezers', category: 'tool', package: null },
  { name: '0 Ohm', category: 'resistor', package: '0603' },
  { name: 'ec360', category: 'capacitor', package: '0805' },
  { name: 'EC100', category: 'capacitor', package: '0805' }
];
const order = (dir) => sortRows(parts, dir).map((p) => p.name).join(' | ');

// category is the primary group, package the secondary, name only sorts inside them
assert.equal(
  order('asc'),
  'EC100 | ec360 | 0 Ohm | 22 Ohm 1% | 100 Ohm 1% | Tweezers',
  'asc: capacitor < resistor < tool, and 0603 before 0805 inside resistor'
);

// Z-A flips names only — the groups stay put and in the same order
assert.equal(
  order('desc'),
  'ec360 | EC100 | 0 Ohm | 100 Ohm 1% | 22 Ohm 1% | Tweezers',
  'desc: group order unchanged, names reversed within each group'
);

// natural numeric compare, not lexicographic
assert.ok(
  order('asc').indexOf('22 Ohm 1%') < order('asc').indexOf('100 Ohm 1%'),
  '22 sorts before 100'
);

// a null package must not throw and must group together
assert.doesNotThrow(() => sortRows([{ name: 'a' }, { name: 'b' }]));
assert.equal(sortRows([]).length, 0);

// the input array is not mutated
const before = parts.map((p) => p.name).join();
sortRows(parts, 'desc');
assert.equal(parts.map((p) => p.name).join(), before, 'sortRows does not mutate its input');

console.log('sort order ok');
// Checks the admin view filters: node test_views.js
import assert from 'assert';
